#include <stdio.h>
#define N 5

int main(void) {
    int A[N][N];            /* 三对角矩阵：|i-j| <= 1 处非零 */
    int b[3*N-2];           /* 压缩存储，共 13 个元素 */
    int k = 0;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if ((i-j)*(i-j) <= 1)   /* 只取三条对角线 */
                b[k++] = A[i][j];
    return 0;
}
